// Generate the mobile HTML guide from the maintained public Markdown source.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '../..');
const { marked } = require(path.join(root, 'app/src/main/assets/content-viewer/vendor/marked.js'));
const source = fs.readFileSync(path.join(root, 'docs/ANDROID_USER_GUIDE.md'), 'utf8');
const body = marked.parse(source, { gfm: true });
const html = `<!doctype html>
<!-- Generated by tools/build/Build-ContentGuides.cjs from docs/ANDROID_USER_GUIDE.md. -->
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'self'; style-src 'self' 'unsafe-inline'; font-src 'self'; img-src 'none'; connect-src 'none'; base-uri 'none'; form-action 'none'">
<title>PaykiTodo 使用说明</title><link rel="stylesheet" href="../content-viewer/viewer.css"></head>
<body><details id="toc" class="enabled"><summary>目录</summary><nav></nav></details><main id="content">${body}</main><script src="wiki.js"></script></body></html>
`;
const output = path.join(root, 'app/src/main/assets/wiki/index.html');
if (process.argv.includes('--check')) {
  if (fs.readFileSync(output, 'utf8') !== html) { console.error('Mobile HTML guide is stale. Run node tools/build/Build-ContentGuides.cjs'); process.exit(1); }
} else fs.writeFileSync(output, html);
